package com.javasmyths.mercenary;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import javax.servlet.http.*;
import java.nio.file.*;
import java.util.*;
@Controller
public class MercenaryController {
 private final ObjectMapper mapper=new ObjectMapper(); private final Path storage;
 @Value("${mercenary.portal-url:http://192.168.1.187:8080/traveller/}") private String portalUrl;
 @Value("${mercenary.public-hosting:false}") private boolean publicHosting;
 @ModelAttribute public void hosting(Model model){model.addAttribute("portalUrl",portalUrl);model.addAttribute("storageNotice",publicHosting?"Records are saved on DoxyLabs and shared with other visitors. Do not enter private information.":"Saved records are local to this computer.");}
 @GetMapping("/health") @ResponseBody public String health(){return "Mercenary OK";}
 public MercenaryController(@Value("${mercenary.storage-dir}") String dir)throws Exception{storage=Paths.get(dir).toAbsolutePath();Files.createDirectories(storage);}
 Soldier current(HttpSession session){Soldier s=(Soldier)session.getAttribute("soldier");if(s==null){s=new Soldier();session.setAttribute("soldier",s);}return s;}
 String csrf(HttpSession session){String t=(String)session.getAttribute("csrf");if(t==null){t=UUID.randomUUID().toString();session.setAttribute("csrf",t);}return t;}
 @GetMapping("/") public String home(HttpSession session,Model model){Soldier s=current(session);model.addAttribute("s",s);model.addAttribute("csrf",csrf(session));model.addAttribute("choices",Rules.choices(s));model.addAttribute("tables",Rules.tables(s));model.addAttribute("transfers",Rules.transferArms(s));model.addAttribute("arms",Rules.ARMS);model.addAttribute("missions",Rules.MISSIONS);model.addAttribute("mos",Rules.MOS[Math.max(0,Rules.arm(s.arm))]);List<int[]> outcomes=new ArrayList<>();for(int i=0;i<7;i++)outcomes.add(Rules.outcomes(s,i));model.addAttribute("outcomes",outcomes);model.addAttribute("cash",Rules.CASH[s.service.equals("Army")?0:1]);model.addAttribute("material",Rules.MATERIAL[s.service.equals("Army")?0:1]);model.addAttribute("officerSpecials",Arrays.asList(Rules.OFFICERS).subList(0,5));Map<String,String[]> charts=new LinkedHashMap<>();for(String t:Rules.tables(s))charts.put(t,Rules.table(s,t));model.addAttribute("charts",charts);return "index";}
 void check(HttpSession session,Map<String,String> p,Soldier s){if(!csrf(session).equals(p.get("csrf")))throw new IllegalArgumentException("This form expired. Reload the page.");if(!Integer.toString(s.revision).equals(p.get("revision")))throw new IllegalArgumentException("That decision is already locked. Reload to continue.");}
 void require(Soldier s,String phase){if(!s.phase.equals(phase))throw new IllegalArgumentException("That stage is locked.");}
 boolean yes(Map<String,String> p,String key){return "on".equals(p.get(key));}
 void persist(Soldier s)throws Exception{Path dest=storage.resolve(s.id+".json"),temp=Files.createTempFile(storage,"save-",".tmp");try{mapper.writerWithDefaultPrettyPrinter().writeValue(temp.toFile(),s);try{Files.move(temp,dest,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,dest,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}}
 @PostMapping("/action") public String action(@RequestParam Map<String,String> p,HttpSession session){synchronized(session){Soldier original=current(session);try{check(session,p,original);Soldier s=mapper.readValue(mapper.writeValueAsBytes(original),Soldier.class);String action=p.getOrDefault("action","");switch(action){
 case "new":s=new Soldier();break;
 case "roll":require(s,"RECRUIT");for(int i=0;i<6;i++)s.stats[i]=Rules.roll(s,new String[]{"STR","DEX","END","INT","EDU","SOC"}[i],2,0);s.rolled=true;break;
 case "enlist":require(s,"RECRUIT");if(!s.rolled)throw new IllegalArgumentException("Roll characteristics first.");s.name=p.getOrDefault("name","").trim();if(s.name.isEmpty()||s.name.length()>80)throw new IllegalArgumentException("Enter a name, up to 80 characters.");s.service=p.getOrDefault("service","");if(!Arrays.asList("Army","Marines").contains(s.service))throw new IllegalArgumentException("Choose Army or Marines.");s.arm=p.getOrDefault("arm","");if(!(s.service.equals("Army")?Arrays.asList("Infantry","Cavalry","Artillery","Support"):Arrays.asList("Marine Infantry","Support")).contains(s.arm))throw new IllegalArgumentException("Choose an arm available in that service.");s.tl=Integer.parseInt(p.getOrDefault("tl","12"));if(s.tl<5||s.tl>15)throw new IllegalArgumentException("Service tech level must be 5–15.");int dm=s.service.equals("Army")?(s.stats[4]>=5?1:0)+(s.stats[2]>=10?2:0):(s.stats[3]>=8?1:0)+(s.stats[0]>=8?2:0);int target=s.service.equals("Army")?5:9;if(Rules.roll(s,"Enlist in "+s.service+" — "+target+"+",2,dm)<target){int draft=Rules.roll(s,"Draft",1,0);String drafted=new String[]{"Navy","Marines","Army","Scouts","Merchants","Other"}[draft-1];Rules.note(s,"Drafted into "+drafted+".");if(!drafted.equals("Army")&&!drafted.equals("Marines")){s.phase="OTHER";Rules.note(s,"This draft leaves Book 4. Continue this recruit with the Book 1 generator, or start a new recruit.");break;}s.service=drafted;s.arm=drafted.equals("Army")?"Infantry":"Marine Infantry";}s.phase="TRAIN";Rules.note(s,"Enlistment locked · "+s.service+" / "+s.arm+" · TL "+s.tl);break;
 case "train":require(s,"TRAIN");Rules.training(s);break;
 case "assign":require(s,"ASSIGN");String forced=p.getOrDefault("forced","");if(s.aide&&!forced.isEmpty()&&!Arrays.asList("Command","Staff","Intelligence school","Command college","Staff college","Commando school","Recruiting").contains(forced))throw new IllegalArgumentException("Choose an available aide assignment.");Rules.assignment(s,yes(p,"education"),yes(p,"buck"),yes(p,"specialDm"),yes(p,"survival"),forced);break;
 case "skill":require(s,"SKILL");String table=p.getOrDefault("table","");if(!Rules.tables(s).contains(table))throw new IllegalArgumentException("That skill table is unavailable.");Rules.skillRoll(s,table);Rules.advance(s);break;
 case "choice":require(s,"CHOICE");String choice=p.getOrDefault("choice","");if(!Rules.choices(s).contains(choice))throw new IllegalArgumentException("Choose an available specialty.");String generic=s.pending.remove(0);String skill=generic.equals("Gun Combat")?choice:generic+": "+choice;s.skills.merge(skill,1,Integer::sum);Rules.note(s,"Selected "+skill+"-"+s.skills.get(skill));if(s.pending.isEmpty())s.phase=s.next;break;
 case "cross":require(s,"CROSS");String arm=p.getOrDefault("arm","");if(arm.equals(s.arm)||arm.equals("Commando")||Rules.arm(arm)<0||s.service.equals("Army")&&arm.equals("Marine Infantry"))throw new IllegalArgumentException("Choose another eligible arm.");if(!s.qualified.contains(arm))s.qualified.add(arm);String old=s.arm;s.arm=arm;Rules.skillRoll(s,"MOS");s.arm=old;Rules.note(s,"Qualified for transfer to "+arm+" at the next term boundary.");Rules.advance(s);break;
 case "term":require(s,"TERM");String transfer=p.getOrDefault("arm",s.arm);if(!Rules.transferArms(s).contains(transfer))throw new IllegalArgumentException("Transfer requires the appropriate training.");boolean reenlist="reenlist".equals(p.get("decision"));int raw=Rules.roll(s,"Re-enlistment — natural 12 is mandatory",2,0);int bonus=s.service.equals("Army")&&!s.officer?2:s.service.equals("Marines")&&(transfer.equals("Cavalry")||transfer.equals("Artillery"))&&!transfer.equals(s.arm)&&s.qualified.contains(transfer)?1:0;Rules.note(s,"Re-enlistment DM "+bonus+"; target "+(s.service.equals("Army")?7:6)+"+.");if(raw==12||reenlist&&s.getCompletedTerms()<7&&raw+bonus>=(s.service.equals("Army")?7:6)){if(!s.arm.equals(transfer))Rules.note(s,"Transferred from "+s.arm+" to "+transfer);s.arm=transfer;s.promoted=false;s.phase="ASSIGN";Rules.note(s,raw==12?"Mandatory re-enlistment. Begin the next term.":"Re-enlisted. Begin the next term.");}else Rules.muster(s);break;
 case "benefit":require(s,"BENEFITS");String benefit=p.getOrDefault("table","");if(!Arrays.asList("Cash","Material").contains(benefit))throw new IllegalArgumentException("Choose Cash or Material.");Rules.benefit(s,benefit,yes(p,"bonus"));break;
 case "save":break;
 default:throw new IllegalArgumentException("Unknown action.");}
 s.revision++;persist(s);session.setAttribute("soldier",s);
 }catch(Exception e){original.message=e instanceof IllegalArgumentException?e.getMessage():"Could not complete that action. Your previous state is intact.";}return "redirect:/";}}
 @GetMapping("/characters") public String library(HttpSession session,Model model)throws Exception{List<Soldier> saved=new ArrayList<>();try(java.util.stream.Stream<Path> files=Files.list(storage)){files.filter(x->x.getFileName().toString().endsWith(".json")).forEach(x->{try{saved.add(mapper.readValue(x.toFile(),Soldier.class));}catch(Exception ignored){}});}saved.sort(Comparator.comparing(x->x.name.toLowerCase()));model.addAttribute("saved",saved);model.addAttribute("csrf",csrf(session));model.addAttribute("revision",current(session).revision);return "library";}
 @PostMapping("/open") public String open(@RequestParam Map<String,String> p,HttpSession session)throws Exception{synchronized(session){check(session,p,current(session));UUID id=UUID.fromString(p.get("id"));Soldier s=mapper.readValue(storage.resolve(id+".json").toFile(),Soldier.class);s.revision++;session.setAttribute("soldier",s);return "redirect:/";}}
 @GetMapping("/export") public ResponseEntity<byte[]> export(HttpSession session)throws Exception{return ResponseEntity.ok().header("Content-Disposition","attachment; filename=mercenary-service-record.json").contentType(MediaType.APPLICATION_JSON).body(mapper.writerWithDefaultPrettyPrinter().writeValueAsBytes(current(session)));}
}
